   get changedFiles(): SessionChange[] {
     const result: SessionChange[] = [];
-    for (const [, fileChanges] of this.changes) {
+    this.forEachFileChanges((fileChanges) => {
       if (fileChanges.length > 0) {
         result.push(fileChanges[fileChanges.length - 1]!);
       }
-    }
+    });
     // Neueste zuerst
     return result.sort((a, b) => b.timestamp - a.timestamp);
   }

   /** Gesamtanzahl Änderungen. */
   get totalChanges(): number {
     let count = 0;
-    for (const changes of this.changes.values()) count += changes.length;
+    this.forEachFileChanges((fileChanges) => {
+      count += fileChanges.length;
+    });
     return count;
   }

+  private forEachFileChanges(callback: (fileChanges: SessionChange[]) => void): void {
+    for (const fileChanges of this.changes.values()) callback(fileChanges);
+  }
+
Pre-existing workspace state (vor der ersten Änderung dieses Tasks erfasst):
clean (git status --short produced no output).

Pre-existing dirty-path fingerprints:
Keine vorbestehenden schmutzigen Pfade; daher keine Fingerprints erforderlich.

Acceptance / Akzeptanzkriterien:
- Nur benchmark-fixture/diff-viewer/change-tracker.ts ist geändert.
- Der private Helper vereinheitlicht die Iteration, ohne Map-Reihenfolge,
  Rückgabewerte, Sortierung, Typen oder Zählung zu verändern.
- Die öffentliche ChangeTracker-Schnittstelle bleibt identisch.
- node benchmark-fixture/run-fixture-test.mjs besteht mit 11/11.
- Die vollständige deklarierte Prüfung wird bewertet; in dieser Umgebung sind
  bekannte EPERM-Fehler beim Spawn von node/git in bestehenden Runtime-Tests
  möglich.

